var e={rows:[{id:`蝠翼`,name:`蝠翼`,effect2:`攻击加成 15%`,effect4:`造成伤害时，附带 20% 吸血。`,category:`攻击`,note:`吸血生存向`},{id:`轮入道`,name:`轮入道`,effect2:`攻击加成 15%`,effect4:`回合结束时，有 20% 概率获得新的回合。`,category:`攻击`},{id:`狰`,name:`狰`,effect2:`攻击加成 15%`,effect4:`受到敌方伤害时，有 35% 概率反击；对被嘲讽目标降低 60% 触发概率。`,category:`攻击`,note:`反击流`},{id:`鸣屋`,name:`鸣屋`,effect2:`攻击加成 15%`,effect4:`攻击时，若目标带有控制效果，提升 45% 伤害。`,category:`攻击`,note:`打控制目标增伤`},{id:`心眼`,name:`心眼`,effect2:`攻击加成 15%`,effect4:`造成伤害时，目标生命比例每降低 15%，提升 10% 伤害。`,category:`攻击`,note:`独立乘区 · 残血收割`},{id:`阴摩罗`,name:`阴摩罗`,effect2:`攻击加成 15%`,effect4:`击败目标时，获得 3 点鬼火。`,category:`攻击`,note:`击杀回火`},{id:`狂骨`,name:`狂骨`,effect2:`攻击加成 15%`,effect4:`造成伤害时，每拥有 1 点鬼火，提升 8% 伤害。`,category:`攻击`,note:`独立乘区`},{id:`兵主部`,name:`兵主部`,effect2:`攻击加成 15%`,effect4:`回合结束后，获得 1 层兵刃。每层将在造成伤害时无视目标 75 点防御，上限 3 层。`,category:`攻击`},{id:`贝吹坊`,name:`贝吹坊`,effect2:`攻击加成 15%`,effect4:`携带者回合开始获得一层可以抵挡一次伤害的贝甲，贝甲存在时提高 25% 的伤害。`,category:`攻击`,note:`加算乘区`},{id:`隐念`,name:`隐念`,effect2:`攻击加成 15%`,effect4:`造成的伤害提升 20%，若对同一目标重复造成伤害，造成的伤害依次提升至 40%、60%，之后从 20% 开始循环判定。`,category:`攻击`,note:`独立乘区`},{id:`尘冢`,name:`尘冢`,effect2:`攻击加成 15%`,effect4:`行动时获得尘冢：造成的伤害提升 25%，友方非召唤物目标每比敌方多一个，伤害额外提升 4%，最多提升至 45%。`,category:`攻击`,note:`独立乘区`},{id:`三味`,name:`三味`,effect2:`暴击 15%`,effect4:`任一友方承受控制效果和放逐时，使其提升 30 点速度，持续 2 回合，此增益效果不可驱散，可叠加 2 层。`,category:`暴击`},{id:`网切`,name:`网切`,effect2:`暴击 15%`,effect4:`攻击时，50% 概率无视 45% 防御。`,category:`暴击`},{id:`伤魂鸟`,name:`伤魂鸟`,effect2:`暴击 15%`,effect4:`任一非怪物目标阵亡时，治疗生命上限 20% 的生命，并提升 20% 伤害（上限 120%）直到战斗结束。`,category:`暴击`,note:`加算乘区 · 无御魂副本产出`},{id:`破势`,name:`破势`,effect2:`暴击 15%`,effect4:`造成伤害时，若目标生命比例高于 70%，提升 40% 伤害。`,category:`暴击`,note:`独立乘区`},{id:`镇墓兽`,name:`镇墓兽`,effect2:`暴击 15%`,effect4:`生命比例每降低 1%，提升暴击伤害的 0.5%。`,category:`暴击`,note:`无任何副本产出`},{id:`针女`,name:`针女`,effect2:`暴击 15%`,effect4:`暴击时，有 40% 概率对目标造成其生命上限 10% 的无视防御伤害，最高不超过攻击 120%。`,category:`暴击`},{id:`青女房`,name:`青女房`,effect2:`暴击 15%`,effect4:`首次受到致命伤害时，移除所有状态和印记，恢复 100% 生命并使自身冰封 1 回合，期间提升 100% 防御、免疫所有减益。若冰封结束时仍存活，则再次恢复 100% 生命。每回目仅触发一次。`,category:`暴击`},{id:`海月火玉`,name:`海月火玉`,effect2:`暴击 15%`,effect4:`鬼火、愿力或义火足够时，施放妖术额外消耗 1 点鬼火、愿力或义火并提升 40% 伤害。`,category:`暴击`,note:`独立乘区`},{id:`应声虫`,name:`应声虫`,effect2:`暴击 15%`,effect4:`携带者获得 20% 协战概率。`,category:`暴击`},{id:`片叶之苇`,name:`片叶之苇`,effect2:`暴击 15%`,effect4:`当前生命等于最大生命时，造成伤害提升 45%。`,category:`暴击`,note:`独立乘区`},{id:`无刀取`,name:`无刀取`,effect2:`暴击伤害 20%`,effect4:`回合结束后，永久提升 15% 的伤害，最高不超过 45%。`,category:`暴击`,note:`全游戏唯一「爆伤两件套」`},{id:`雪幽魂`,name:`雪幽魂`,effect2:`防御加成 30%`,effect4:`造成伤害时，有 15%（若目标带有减速效果则为 30%）基础概率冰冻 1 回合；受到攻击时，使攻击者减速 30 点，持续 1 回合。`,category:`防御`},{id:`招财猫`,name:`招财猫`,effect2:`防御加成 30%`,effect4:`回合开始时，有 50% 的概率获得 2 点鬼火。`,category:`防御`,note:`打火`},{id:`反枕`,name:`反枕`,effect2:`防御加成 30%`,effect4:`造成伤害时，有 23% 基础概率使目标沉睡 1 回合。`,category:`防御`},{id:`日女巳时`,name:`日女巳时`,effect2:`防御加成 30%`,effect4:`造成伤害时，有 20% 概率击退目标 30% 行动条，若其带有增益状态、印记，触发概率提升 10%。`,category:`防御`},{id:`珍珠`,name:`珍珠`,effect2:`防御加成 30%`,effect4:`治疗时，目标获得不可驱散的护盾 2 回合，能吸收等同基础治疗 30% 的伤害。`,category:`防御`,note:`无御魂副本产出`},{id:`魅妖`,name:`魅妖`,effect2:`防御加成 30%`,effect4:`造成伤害时，有 25% 基础概率使目标混乱 1 回合。`,category:`防御`},{id:`木魅`,name:`木魅`,effect2:`防御加成 30%`,effect4:`任何友方受到伤害时，有 25% 概率削减伤害者 1 点鬼火，单次攻击内最多触发 1 次；对被嘲讽目标降低 60% 触发概率。`,category:`防御`},{id:`出世螺`,name:`出世螺`,effect2:`防御加成 30%`,effect4:`每次受到伤害后恢复该伤害 10% 的生命值。在战斗开始与自身行动前获得螺壳（上限 1 层），单次受到超过最大生命 60% 的伤害时，将该伤害降低为最大生命的 60%，并移除螺壳。`,category:`防御`},{id:`火之车`,name:`火之车`,effect2:`防御加成 30%`,effect4:`携带者回合结束时，获得 1 层墓火，累计 4 层时清空层数并获得 1 个回合，且该回合鬼火消耗减少 1 点。`,category:`防御`},{id:`奉海图`,name:`奉海图`,effect2:`防御加成 30%`,effect4:`唯一效果，友方受到攻击时获得海图守护，持续 1 回合。海图守护：降低此次伤害的 30%（不超过携带者生命上限的 35%）并记录，消失时失去等同于记录值的生命。`,category:`防御`,note:`唯一效果`},{id:`雨降`,name:`雨降`,effect2:`防御加成 30%`,effect4:`生命首次低于 30% 时，将自身生命上限降低至 1 点并获得 3 层雨露。雨露：受到伤害时，消耗 1 层并吸收此次行动内的所有伤害。`,category:`防御`},{id:`地藏像`,name:`地藏像`,effect2:`生命加成 15%`,effect4:`受到暴击时，自身 100%、友方 30% 概率获得 1 回合护盾，能吸收 10% 生命上限的伤害；对被嘲讽目标降低 60% 触发概率。`,category:`生命`},{id:`涅槃之火`,name:`涅槃之火`,effect2:`生命加成 15%`,effect4:`行动结束时，若生命比例低于 30%，治疗生命上限 15% 的生命。`,category:`生命`},{id:`被服`,name:`被服`,effect2:`生命加成 15%`,effect4:`30% 减伤。`,category:`生命`},{id:`镜姬`,name:`镜姬`,effect2:`生命加成 15%`,effect4:`受到伤害时，有 30% 概率造成 100% 反伤；对被嘲讽目标降低 60% 触发概率。`,category:`生命`},{id:`钟灵`,name:`钟灵`,effect2:`生命加成 15%`,effect4:`造成伤害时，有 10% 基础概率使目标眩晕 1 回合。若敌方无人处于眩晕中，则基础概率改为 20%。`,category:`生命`},{id:`树妖`,name:`树妖`,effect2:`生命加成 15%`,effect4:`治疗时，增加 20%（若目标生命低于 20%，改为增加 50%）基础治疗。`,category:`生命`,note:`奶妈向`},{id:`薙魂`,name:`薙魂`,effect2:`生命加成 15%`,effect4:`唯一效果。友方被攻击时 50% 概率守护，使其中的单体伤害降低 20%，再分担 50%，直到攻击结束。每次攻击最多触发一次。`,category:`生命`},{id:`涂佛`,name:`涂佛`,effect2:`生命加成 15%`,effect4:`唯一效果。回合结束时，若本回合普攻或无法动作，使友方全体提升 15% 效果抵抗、伤害，维持 2 回合，自身提升双倍。`,category:`生命`,note:`加算乘区`},{id:`恶楼`,name:`恶楼`,effect2:`生命加成 15%`,effect4:`战斗开始时，获得恶楼之力（增伤 80%、减伤 80%）。在携带者的前 8 回合，恶楼之力暂时被封禁。`,category:`生命`,note:`加算乘区`},{id:`叠叩`,name:`叠叩`,effect2:`生命加成 15%`,effect4:`（唯一效果）若自身初始暴击超过 120% 时，全体非召唤物友方减少 15% 受到的暴击伤害。`,category:`生命`,note:`唯一效果`},{id:`夜啼石`,name:`夜啼石`,effect2:`生命加成 15%`,effect4:`唯一效果。友方非召唤物目标阵亡时，获得其初始攻击、防御与生命的 30%，持续 2 回合（上限 5 层，且最多不超过携带者初始属性的 150%）。`,category:`生命`,note:`唯一效果`},{id:`火灵`,name:`火灵`,effect2:`效果命中 15%`,effect4:`战斗开始时，获得 3 点鬼火。`,category:`效果命中`,note:`打火 · 只周末出`},{id:`蚌精`,name:`蚌精`,effect2:`效果命中 15%`,effect4:`战斗开始时，友方全体获得无法驱散的护盾 1 回合，能吸收等同生命上限 10% 的伤害。`,category:`效果命中`},{id:`飞缘魔`,name:`飞缘魔`,effect2:`效果命中 15%`,effect4:`附加负面状态时，无视 30% 总效果抵抗。`,category:`效果命中`},{id:`遗念火`,name:`遗念火`,effect2:`效果命中 15%`,effect4:`携带者回合开始时获得 1 层念火（上限 3 层），每层提供 15% 效果抵抗，携带者施放技能时优先消耗自身念火替代等量鬼火。`,category:`效果命中`},{id:`元兴寺`,name:`元兴寺`,effect2:`效果命中 15%`,effect4:`（唯一效果）携带者回合内造成控制效果时，每命中 1 个目标，使全体非召唤物友方造成的伤害提升 5%（重复命中同目标仅生效 1 次），最多提升 40%，持续 2 回合。`,category:`效果命中`,note:`加算乘区`},{id:`油赤子`,name:`油赤子`,effect2:`效果命中 15%`,effect4:`唯一效果。战斗开始时获得 2 层灵元，灵元：每层提升友方全体 8% 的防御，友方施放妖术时若鬼火不足，可替代等量鬼火。`,category:`效果命中`,note:`唯一效果`},{id:`魍魉之匣`,name:`魍魉之匣`,effect2:`效果抵抗 15%`,effect4:`造成伤害时，有 25% 基础概率随机附加眩晕、沉默、减疗 40%、混乱，持续 1 回合。`,category:`效果抵抗`},{id:`骰子鬼`,name:`骰子鬼`,effect2:`效果抵抗 15%`,effect4:`抵抗时，反击来源目标，该次反击提升 50% 伤害。未被控制时承受控制效果，增加 25% 行动条。`,category:`效果抵抗`,note:`无御魂副本产出`},{id:`返魂香`,name:`返魂香`,effect2:`效果抵抗 15%`,effect4:`受到伤害时，有 25% 基础概率使伤害者眩晕 1 回合；对被嘲讽目标降低 60% 触发概率。`,category:`效果抵抗`},{id:`幽谷响`,name:`幽谷响`,effect2:`效果抵抗 15%`,effect4:`抵抗控制效果时，有 50% 概率将该效果反弹给来源目标，且必定命中。`,category:`效果抵抗`},{id:`共潜`,name:`共潜`,effect2:`效果抵抗 15%`,effect4:`回合结束时随机驱散己方 1 个负面状态，若回合中未造成伤害，则额外随机驱散己方 2 个负面状态。`,category:`效果抵抗`},{id:`钓瓶火`,name:`钓瓶火`,effect2:`效果抵抗 15%`,effect4:`回合结束后，额外推进 1 格鬼火行动条，并为当前生命比例最低的非召唤物友方目标治疗自身防御 700% 的生命。`,category:`效果抵抗`},{id:`夜送犬`,name:`夜送犬`,effect2:`效果抵抗 15%`,effect4:`每回合首次受到来自敌方的控制效果时，获得 1 层夜行。夜行：提升 80% 抵抗，上限 3 层，携带者回合开始处于可行动状态时移除。`,category:`效果抵抗`},{id:`土蜘蛛`,name:`土蜘蛛`,effect2:`唯一被动，对怪物造成伤害时，为其附加 1 层土蜘蛛印记，降低 10% 速度，并造成 10% 间接伤害，持续 1 回合。上限 3 层。`,category:`首领`,note:`单件给随机属性`},{id:`胧车`,name:`胧车`,effect2:`唯一被动，受到怪物攻击时，有 50% 概率增加 30% 行动条，单次攻击内最多触发 1 次。`,category:`首领`,note:`单件给随机属性`},{id:`荒骷髅`,name:`荒骷髅`,effect2:`唯一被动，提升 10% 对怪物伤害，若受到怪物攻击，提升伤害效果改为 25%，持续 1 回合。`,category:`首领`,note:`独立乘区`},{id:`地震鲶`,name:`地震鲶`,effect2:`唯一被动，与怪物的战斗开始时，获得 60% 减伤；每次受到伤害，将 6% 减伤转化为提升 1.5% 伤害，单次攻击内最多触发 1 次。`,category:`首领`,note:`加算乘区`},{id:`蜃气楼`,name:`蜃气楼`,effect2:`唯一被动，与怪物的战斗开始时，获得庇护。庇护会在消失后 5 回合重新获得。`,category:`首领`,note:`单件给随机属性`},{id:`鬼灵歌伎`,name:`鬼灵歌伎`,effect2:`唯一被动，每对怪物造成 5 次伤害后，下一次对怪物造成伤害将会对其造成生命上限 20% 的无视防御伤害，最高不超过攻击的 255%。`,category:`首领`,note:`单件给随机属性`},{id:`夜荒魂`,name:`夜荒魂`,effect2:`唯一被动，携带者回合内对怪物造成控制效果或放逐时，每命中 1 个目标，使全体非召唤物友方提升 15 点速度（重复命中同目标仅生效 1 次），最多提升 90 点，维持 1 回合。`,category:`首领`,note:`十周年新增`},{id:`八咫镜`,name:`八咫镜`,effect2:`唯一效果，与怪物战斗时，造成伤害施加光灼，再次施加光灼时移除并提升 20% 伤害。`,category:`首领`,note:`单件给随机属性`},{id:`天羽羽斩`,name:`天羽羽斩`,effect2:`与怪物战斗时，战斗开始获得 50 点无视防御。`,category:`首领`,note:`单件给随机属性`},{id:`预言星盘`,name:`预言星盘`,effect2:`唯一效果，与怪物战斗时施放妖术技能，提升阴阳师暴击，提升值为自身暴击的 15%。`,category:`首领`,note:`单件给随机属性`},{id:`月之石`,name:`月之石`,effect2:`唯一效果，友方召唤物存在时，敌方怪物总效果抵抗降低 30%（不超过自身初始效果抵抗的 50%）。`,category:`首领`,note:`单件给随机属性`},{id:`纺缘锤`,name:`纺缘锤`,effect2:`战斗开始与自身每个回合开始时获得缘守。缘守：受到怪物攻击后格挡 500 点伤害，格挡初始防御 300% 的伤害后移除。`,category:`首领`,note:`单件给随机属性`},{id:`稻荷穗箭`,name:`稻荷穗箭`,effect2:`唯一效果，与怪物战斗时，回合结束后提升阴阳师 10% 行动条（阴阳师回合开始前限 1 次）。`,category:`首领`,note:`单件给随机属性`}]};export{e as default};